Post Date: 2015-11-19T17:31:34Z
Current Date: April 4 2025
Title: Make TemplatedPathPlugin's replacePathVariables available as a utility.
Description: I am working on writing a plugin that produces a manifest file when a webpack build completes.

As options to the plugin, I want to be able to let the user specify filenames/paths using webpack's available values such as `[chunk]`, etc.

Right now, that logic is tied up with the TemplatedPathPlugin.

I would like to break it out so that I can do something like this for my own webpack plugin:
## Plugin

```
var replacePathVariables = require( 'webpack/lib/TemplatedPathHelper' ).replacePathVariables;

function manifestPluginFactory( opts ) {
    return function() {
        this.plugin( 'done', function( stats ) {
            var manifestContents = _.chain( stats.compilation.namedChunks )
                .map( function( chunk ) {
                    // The key is the canonical way to reference the
                    // file.
                    var key = chunk.name;
                    // Get the root directory
                    var serverPath = path.join( opts.root, opts.path, opts.fileName );
                    // Leverage existing webpack replacePathVariables method
                    stats.chunk = chunk;
                    serverPath = replacePathVariables( serverPath, stats );
                    return [ key, serverPath ];
                } )
                .object()
                .value();
            fs.writeFileSync( opts.manifestDest, JSON.stringify( manifestContents ) );
        } );
    }
}
```
## Webpack Config

```
{ plugins: [
    manifestPluginFactory( {
        root: '/webpack/build/',
        path: '[hash]/mobile/',
        fileName: '[name].js',
        manifestDest: 'path.join( process.cwd(), 'webpack/build/manifest.json' )'
    } )
] }
```
